type ignoreFlag map[string]*regexp.Regexp

func (f ignoreFlag) String() string { return "" }
func (f ignoreFlag) Set(s string) error {
	pairs := strings.Split(s, ",")
	for _, pair := range pairs {
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) == 1 {
			re, err := regexp.Compile(parts[0])
			if err != nil {
				return err
			}
			f[""] = re
		} else {
			re, err := regexp.Compile(parts[1])
			if err != nil {
				return err
			}
			f[parts[0]] = re
		}
	}
	return nil
}

var (
	abspath         = flag.Bool("abspath", false, "")
	asserts         = flag.Bool("asserts", false, "")
	blank           = flag.Bool("blank", false, "")
	excludeFile     = flag.String("exclude", "", "")
	excludeOnly     = flag.Bool("excludeonly", false, "")
	ignore          = make(ignoreFlag)
	ignorepkg       = flag.String("ignorepkg", "", "")
	ignoretests     = flag.Bool("ignoretests", false, "")
	ignoregenerated = flag.Bool("ignoregenerated", false, "")
	mod             = flag.String("mod", "", "")
	tags            = flag.String("tags", "", "")
	verbose         = flag.Bool("verbose", false, "")
)

func init() {
	flag.Var(ignore, "ignore", "")
}

func main() {
	flag.Parse()
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(2)
	}
}

var defaultExcludes = []string{
	"fmt.Print", "fmt.Printf", "fmt.Println",
	"fmt.Fprint", "fmt.Fprintf", "fmt.Fprintln",
	"fmt.Sprint", "fmt.Sprintf", "fmt.Sprintln",
    "math/rand.Read",
}

func run() error {
	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

    var excludes []string
    if *excludeFile != "" {
        f, err := os.Open(*excludeFile)
        if err != nil {
            return fmt.Errorf("Could not read exclude file: %v", err)
        }
        defer f.Close()
        scanner := bufio.NewScanner(f)
        for scanner.Scan() {
            line := strings.TrimSpace(scanner.Text())
            if line != "" && !strings.HasPrefix(line, "//") {
                excludes = append(excludes, line)
            }
        }
    }

	var foundAny bool
	for _, path := range paths {
		fset := token.NewFileSet()
		var files []*ast.File

        if info, err := os.Stat(path); err == nil && !info.IsDir() {
            f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
            if err != nil {
                return fmt.Errorf("failed to check packages: %v", err)
            }
            files = append(files, f)
        } else {
            err := filepath.Walk(path, func(p string, fi os.FileInfo, err error) error {
                if err != nil { return err }
                if fi.IsDir() && p != path && strings.HasSuffix(p, "/...") { return nil } // simplified
                if !fi.IsDir() && strings.HasSuffix(p, ".go") {
                    if *ignoretests && strings.HasSuffix(p, "_test.go") {
                        return nil
                    }
                    f, err := parser.ParseFile(fset, p, nil, parser.ParseComments)
                    if err != nil { return err }
                    files = append(files, f)
                }
                return nil
            })
            if err != nil {
                return fmt.Errorf("failed to check packages: %v", err)
            }
        }

		if len(files) == 0 {
			continue
		}

		conf := types.Config{Importer: importer.Default(), Error: func(err error) {}}
		info := &types.Info{
			Types: make(map[ast.Expr]types.TypeAndValue),
			Uses:  make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
		}
		_, _ = conf.Check(files[0].Name.Name, fset, files, info)

		if checkFiles(fset, info, files, excludes) {
			foundAny = true
		}
	}

	if foundAny {
		os.Exit(1)
	}
	return nil
