func checkFiles(fset *token.FileSet, info *types.Info, files []*ast.File, excludes []string) bool {
	var found bool
	for _, f := range files {
		ast.Inspect(f, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.ExprStmt:
				if call, ok := node.X.(*ast.CallExpr); ok {
					if flagCall(fset, info, call, nil, excludes) {
						found = true
					}
				}
			case *ast.AssignStmt:
				for i, rhs := range node.Rhs {
					if call, ok := rhs.(*ast.CallExpr); ok {
						var lhs []ast.Expr
						if len(node.Rhs) == 1 {
							lhs = node.Lhs
						} else if len(node.Lhs) > i {
							lhs = []ast.Expr{node.Lhs[i]}
						}
						if flagCall(fset, info, call, lhs, excludes) {
							found = true
						}
					} else if ta, ok := rhs.(*ast.TypeAssertExpr); ok && *asserts {
                        var lhs []ast.Expr
						if len(node.Rhs) == 1 {
							lhs = node.Lhs
						} else if len(node.Lhs) > i {
							lhs = []ast.Expr{node.Lhs[i]}
						}
                        if flagTypeAssert(fset, info, ta, lhs) {
                            found = true
                        }
                    }
				}
			}
			return true
		})
	}
	return found
}

func isError(t types.Type) bool {
	if t == nil { return false }
    errInterface := types.Universe.Lookup("error").Type().Underlying().(*types.Interface)
    return types.Implements(t, errInterface)
}

func flagCall(fset *token.FileSet, info *types.Info, call *ast.CallExpr, lhs []ast.Expr, excludes []string) bool {
    t := info.Types[call].Type
    if t == nil { return false }

    var results []types.Type
    if tuple, ok := t.(*types.Tuple); ok {
        for i := 0; i < tuple.Len(); i++ {
            results = append(results, tuple.At(i).Type())
        }
    } else {
        results = append(results, t)
    }

    var found bool
    for i, res := range results {
        if isError(res) {
            ignored := false
            var pos token.Pos
            if lhs == nil {
                ignored = true
                pos = call.Lparen
            } else if len(lhs) > i {
                if id, ok := lhs[i].(*ast.Ident); ok && id.Name == "_" {
                    ignored = true
                    pos = id.Pos()
                } else if !*blank {
                    // assigned to a variable, so not ignored
                } else if *blank {
                    // with -blank, any assignment to _ is flagged.
                    // But if it's assigned to a variable, it's NOT flagged by -blank.
                }
            } else {
                ignored = true
                pos = call.Lparen
            }

            if ignored && !isExcludedCall(info, call, excludes) {
                if !*blank && lhs != nil {
                    // by default, assigned to _ is not flagged.
                    continue
                }
                report(fset, pos)
                found = true
            }
        }
    }
    return found
}

func flagTypeAssert(fset *token.FileSet, info *types.Info, ta *ast.TypeAssertExpr, lhs []ast.Expr) bool {
    if len(lhs) < 2 {
        report(fset, ta.X.Pos())
        return true
    } else if id, ok := lhs[1].(*ast.Ident); ok && id.Name == "_" {
        if *blank {
            report(fset, id.Pos())
            return true
        }
    }
    return false
}

func isExcludedCall(info *types.Info, call *ast.CallExpr, excludes []string) bool {
    var fn *types.Func
    switch x := call.Fun.(type) {
    case *ast.Ident:
        if obj, ok := info.Uses[x]; ok { fn, _ = obj.(*types.Func) }
    case *ast.SelectorExpr:
        if sel, ok := info.Selections[x]; ok { fn = sel.Obj().(*types.Func) }
        else if obj, ok := info.Uses[x.Sel]; ok { fn, _ = obj.(*types.Func) }
    }
    if fn == nil { return false }

    fullName := fn.FullName()
    // FullName is in format "pkg.Func" or "pkg.(*Receiver).Method"
    // Convert to the format used in excludes: "pkg.Func" or "(*pkg.Receiver).Method"
    sig := fullName
    if fn.Type().(*types.Signature).Recv() != nil {
        recv := fn.Type().(*types.Signature).Recv().Type().String()
        sig = fmt.Sprintf("(%s).%s", recv, fn.Name())
    }

