    pkg := fn.Pkg().Path()
    if re, ok := ignore[pkg]; ok {
        if re.MatchString(fn.Name()) { return true }
    }
    if re, ok := ignore[""]; ok {
        if re.MatchString(fn.Name()) { return true }
    }

    // Check ignorepkg
    for _, p := range strings.Split(*ignorepkg, ",") {
        if p != "" && p == pkg { return true }
    }

    return false
}

func report(fset *token.FileSet, pos token.Pos) {
	p := fset.Position(pos)
	lineContent := ""
	if f, err := os.Open(p.Filename); err == nil {
		defer f.Close()
		scanner := bufio.NewScanner(f)
		for i := 1; i <= p.Line; i++ {
			if scanner.Scan() {
				if i == p.Line { lineContent = scanner.Text() }
			}
		}
	}
    column := 1
    for i, r := range lineContent {
        if i+1 >= p.Column { break }
        if r == '\t' { column += 8 - ((column-1)%8) }
        else { column++ }
    }
    path := p.Filename
    if *abspath {
        if abs, err := filepath.Abs(path); err == nil { path = abs }
    }
	fmt.Printf("%s:%d:%d:\t%s\n", path, p.Line, column, lineContent)
}
EOF
