		if isError(res) {
			ignored := false
			var pos token.Pos
			if lhs == nil {
				ignored = true
				pos = call.Lparen
			} else if len(lhs) > i {
				if id, ok := lhs[i].(*ast.Ident); ok && id.Name == "_" {
					ignored = true
					pos = id.Pos()
				}
			} else {
				ignored = true
				pos = call.Lparen
			}

			if ignored && !isExcludedCall(info, call, excludes) {
				if !*blank && lhs != nil {
					continue
				}
				report(fset, pos)
				found = true
			}
		}
	}
	return found
}

func flagTypeAssert(fset *token.FileSet, info *types.Info, ta *ast.TypeAssertExpr, lhs []ast.Expr) bool {
	if len(lhs) < 2 {
		report(fset, ta.X.Pos())
		return true
	} else if id, ok := lhs[1].(*ast.Ident); ok && id.Name == "_" {
		if *blank {
			report(fset, id.Pos())
			return true
		}
	}
	return false
}

func isExcludedCall(info *types.Info, call *ast.CallExpr, excludes []string) bool {
	var fn *types.Func
	switch x := call.Fun.(type) {
	case *ast.Ident:
		if obj, ok := info.Uses[x]; ok {
			fn, _ = obj.(*types.Func)
		}
	case *ast.SelectorExpr:
		if sel, ok := info.Selections[x]; ok {
			fn = sel.Obj().(*types.Func)
		} else if obj, ok := info.Uses[x.Sel]; ok {
			fn, _ = obj.(*types.Func)
		}
	}
	if fn == nil {
		return false
	}

	fullName := fn.FullName()
	sig := fullName
	if fn.Type().(*types.Signature).Recv() != nil {
		recv := fn.Type().(*types.Signature).Recv().Type().String()
		sig = fmt.Sprintf("(%s).%s", recv, fn.Name())
	}

	if !*excludeOnly {
		for _, ex := range defaultExcludes {
			if strings.Contains(sig, ex) {
				return true
			}
		}
	}
	for _, ex := range excludes {
		if strings.HasPrefix(sig, ex) {
			return true
		}
	}

	pkg := ""
	if fn.Pkg() != nil {
		pkg = fn.Pkg().Path()
	}
	if re, ok := ignore[pkg]; ok {
		if re.MatchString(fn.Name()) {
			return true
		}
	}
	if re, ok := ignore[""]; ok {
		if re.MatchString(fn.Name()) {
			return true
		}
	}

	for _, p := range strings.Split(*ignorepkg, ",") {
		if p != "" && p == pkg {
			return true
		}
	}

	return false
}

func report(fset *token.FileSet, pos token.Pos) {
	p := fset.Position(pos)
	lineContent := ""
	if f, err := os.Open(p.Filename); err == nil {
		defer f.Close()
		scanner := bufio.NewScanner(f)
		for i := 1; i <= p.Line; i++ {
			if scanner.Scan() {
				if i == p.Line {
					lineContent = scanner.Text()
				}
			}
		}
	}
	column := 1
	for i, r := range lineContent {
		if i+1 >= p.Column {
			break
		}
		if r == '\t' {
			column += 8 - ((column - 1) % 8)
		} else {
			column++
		}
	}
	path := p.Filename
	if *abspath {
		if abs, err := filepath.Abs(path); err == nil {
			path = abs
		}
	}
	fmt.Printf("%s:%d:%d:\t%s\n", path, p.Line, column, lineContent)
}
