func run() error {
	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	var excludes []string
	if *excludeFile != "" {
		f, err := os.Open(*excludeFile)
		if err != nil {
			return fmt.Errorf("Could not read exclude file: %v", err)
		}
		defer f.Close()
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
