func checkFiles(fset *token.FileSet, info *types.Info, files []*ast.File, excludes []string) bool {
	var found bool
	for _, f := range files {
		ast.Inspect(f, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.ExprStmt:
				if call, ok := node.X.(*ast.CallExpr); ok {
					if flagCall(fset, info, call, nil, excludes) {
						found = true
					}
				}
			case *ast.AssignStmt:
				for i, rhs := range node.Rhs {
					if call, ok := rhs.(*ast.CallExpr); ok {
						var lhs []ast.Expr
						if len(node.Rhs) == 1 {
							lhs = node.Lhs
						} else if len(node.Lhs) > i {
